def solve():
    ra = Q(P["R_A"])
    ru = Q(P["R_U"])
    d = P["DIRECTION"]
    pct = Q(P["TRADE_PCT"]) / 100
    fee = Q(P["FEE_BPS"]) / 10000
    s = Q(P["SHOCK"]) / 100
    if ra <= 0 or ru <= 0:
        raise ValueError("reserves must be positive")
    if fee >= 1 or pct <= 0:
        raise ValueError("invalid fee or trade size")
    if d not in ("sell_a", "buy_a"):
        raise ValueError("unknown direction")
    k = ra * ru
    spot = ru / ra
    if d == "sell_a":
        rin, rout = ra, ru
    else:
        rin, rout = ru, ra
    x = rin * pct
    net = x * (1 - fee)
    out = rout - k / (rin + net)
    post_in = rin + x
    if d == "sell_a":
        eff = out / x
    else:
        eff = x / out
    impact = (eff / spot - 1) * 100
    bench = spot * (1 + s)
    if d == "sell_a":
        result = out - x * bench
    else:
        result = out * bench - x
    return {"final": result, "output_amount": out, "post_input_reserve": post_in, "price_impact": impact}
